VALUES
('cadastros.produtos.estoque_minimo','Produtos · Estoque','Estoque mínimo','A menor quantidade que você quer ter em estoque, na unidade do produto.','Quando o saldo chega nesse número, o produto aparece como "baixo" e entra na sugestão de compra.','Filtro de óleo: mínimo 5.','Deixar zero: o sistema nunca avisa que está acabando.',20,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.estoque_maximo','Produtos · Estoque','Estoque máximo','A maior quantidade que vale a pena manter parada.','Limita a sugestão de compra, para não comprar demais e prender dinheiro.','Filtro de óleo: máximo 40.','Colocar máximo menor que o mínimo — o sistema não deixa salvar.',21,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.unidade_compra','Produtos · Compra','Unidade de compra','A unidade em que o fornecedor vende (CX, FD, PC).','Permite comprar em caixa e controlar o estoque em unidade, convertendo pelo fator.','Compra em CX, estoque em UN.','Esquecer o fator de conversão junto.',22,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.fator_conversao','Produtos · Compra','Fator de conversão','Quantas unidades de estoque cabem em 1 unidade de compra.','Na entrada da nota, converte a quantidade comprada para a unidade do estoque.','1 CX = 12 UN → fator 12.','Informar 1 quando a caixa tem várias unidades: o estoque entra errado.',23,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.prazo_entrega','Produtos · Compra','Prazo de entrega (dias)','Quantos dias o fornecedor leva para entregar, em número inteiro.','Ajuda a decidir quando comprar para não faltar produto.','7 dias.','Colocar horas ou texto: use só o número de dias.',24,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.controla_lote','Produtos · Estoque','Controla lote','Marque se o produto é recebido e rastreado por lote.','Passa a exigir o número do lote na entrada e na saída.','Tintas, óleos, alimentos.','Marcar em produto comum: dá trabalho sem necessidade.',25,'/dashboard/cadastros/produtos','gestao_empresarial','publicado'),
('cadastros.produtos.controla_validade','Produtos · Estoque','Controla validade','Marque se o produto tem data de validade.','Avisa os lotes perto de vencer e evita vender produto vencido.','Aditivos, tintas, medicamentos.','Marcar sem controlar lote: a validade fica solta.',26,'/dashboard/cadastros/produtos','gestao_empresarial','publicado')
